func trashLabel(kind trash.Kind) string {
	switch kind {
	case trash.Pages:
		return "Page"
	case trash.News:
		return "News"
	case trash.Submissions:
		return "Form submission"
	case trash.Media:
		return "Media"
	default:
		return "Item"
	}
}

func trashActionPath(kind trash.Kind, id string, restore bool) string {
	action := "delete"
	if restore {
		action = "restore"
	}
	return "/admin/trash/" + url.PathEscape(string(kind)) + "/" + url.PathEscape(id) + "/" + action
}

